ALTER TABLE public.vehicles ADD COLUMN IF NOT EXISTS target_consumption numeric, ADD COLUMN IF NOT EXISTS alert_threshold integer NOT NULL DEFAULT 10, ADD COLUMN IF NOT EXISTS monthly_fuel_budget numeric, ADD COLUMN IF NOT EXISTS alerts_enabled boolean NOT NULL DEFAULT true; CREATE TABLE IF NOT EXISTS public.fuel_audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, vehicle_id uuid, fuel_entry_id uuid, action text NOT NULL, actor_name text, odometer_before numeric, odometer_after numeric, changes jsonb NOT NULL DEFAULT '{}'::jsonb, warnings text[] NOT NULL DEFAULT '{}'::text[], notes text, created_at timestamp with time zone NOT NULL DEFAULT now()); GRANT SELECT, INSERT ON public.fuel_audit_log TO authenticated; GRANT ALL ON public.fuel_audit_log TO service_role; ALTER TABLE public.fuel_audit_log ENABLE ROW LEVEL SECURITY; CREATE POLICY fuel_audit_select_own ON public.fuel_audit_log FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY fuel_audit_insert_own ON public.fuel_audit_log FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE INDEX IF NOT EXISTS fuel_audit_log_user_created_idx ON public.fuel_audit_log (user_id, created_at DESC); CREATE INDEX IF NOT EXISTS fuel_audit_log_vehicle_idx ON public.fuel_audit_log (vehicle_id);